#!/usr/bin/env bash
#
# Bump vivgrid/homebrew-tap Formula/sjq.rb to a new sjq release.
#
# Usage: bump-homebrew-tap.sh <tag>   e.g. bump-homebrew-tap.sh v1.1.0
#
# Reads the .sha256 files published on the sjq release, rewrites the formula
# (version + 4 platform urls + 4 sha256s) and pushes to the tap repo.
# Exits 0 with no commit when the formula is already up to date.
#
# Requires: TAP_TOKEN env var (fine-grained PAT with Contents read+write
# on vivgrid/homebrew-tap).

set -euo pipefail

TAG="${1:?usage: bump-homebrew-tap.sh <tag>}"
VERSION="${TAG#v}"
REPO="vivgrid/sjq"
TAP_REPO="vivgrid/homebrew-tap"
FORMULA="Formula/sjq.rb"

# tarball asset -> checksum asset published by upload-rust-binary-action
declare -A CHECKSUM_ASSET=(
  ["sjq-aarch64-apple-darwin.tar.gz"]="sjq-aarch64-apple-darwin.sha256"
  ["sjq-x86_64-apple-darwin.tar.gz"]="sjq-x86_64-apple-darwin.sha256"
  ["sjq-aarch64-unknown-linux-musl.tar.gz"]="sjq-aarch64-unknown-linux-musl.sha256"
  ["sjq-x86_64-unknown-linux-musl.tar.gz"]="sjq-x86_64-unknown-linux-musl.sha256"
)

if [[ -z "${TAP_TOKEN:-}" ]]; then
  echo "ERROR: TAP_TOKEN is not set" >&2
  exit 1
fi

workdir="$(mktemp -d)"
trap 'rm -rf "$workdir"' EXIT

# 1. Fetch sha256 for each release asset. On a direct publish the `published`
#    event can fire before the Release workflow finishes uploading, so wait
#    for the assets (up to 30 minutes).
declare -A SHAS
fetch_shas() {
  for asset in "${!CHECKSUM_ASSET[@]}"; do
    sum_asset="${CHECKSUM_ASSET[$asset]}"
    url="https://github.com/${REPO}/releases/download/${TAG}/${sum_asset}"
    line="$(curl -fsSL --retry 3 "$url" 2>/dev/null)" || return 1
    sha="$(echo "$line" | awk '{print $1}')"
    [[ "$sha" =~ ^[0-9a-f]{64}$ ]] || return 1
    SHAS["$asset"]="$sha"
  done
}

echo "Waiting for release assets of $TAG..."
deadline=$(( $(date +%s) + 1800 ))
while true; do
  if fetch_shas; then
    echo "All checksums fetched."
    break
  fi
  if (( $(date +%s) >= deadline )); then
    echo "ERROR: timed out waiting for $TAG release assets" >&2
    exit 1
  fi
  echo "Assets not ready yet; retrying in 60s..."
  sleep 60
done

# 2. Clone the tap (token via header, never in the URL) and rewrite the formula.
auth_header="$(printf 'x-access-token:%s' "$TAP_TOKEN" | base64 -w0)"
git -c "http.https://github.com/.extraHeader=AUTHORIZATION: basic ${auth_header}" \
  clone --depth 1 "https://github.com/${TAP_REPO}.git" "$workdir/tap"
cd "$workdir/tap"

export SJQ_VERSION="$VERSION" SJQ_TAG="$TAG"
export SJQ_SHA_AARCH64_DARWIN="${SHAS[sjq-aarch64-apple-darwin.tar.gz]}"
export SJQ_SHA_X86_64_DARWIN="${SHAS[sjq-x86_64-apple-darwin.tar.gz]}"
export SJQ_SHA_AARCH64_LINUX="${SHAS[sjq-aarch64-unknown-linux-musl.tar.gz]}"
export SJQ_SHA_X86_64_LINUX="${SHAS[sjq-x86_64-unknown-linux-musl.tar.gz]}"

python3 - "$FORMULA" <<'EOF'
import os, re, sys

path = sys.argv[1]
version = os.environ["SJQ_VERSION"]
tag = os.environ["SJQ_TAG"]
shas = {
    "sjq-aarch64-apple-darwin.tar.gz":      os.environ["SJQ_SHA_AARCH64_DARWIN"],
    "sjq-x86_64-apple-darwin.tar.gz":       os.environ["SJQ_SHA_X86_64_DARWIN"],
    "sjq-aarch64-unknown-linux-musl.tar.gz": os.environ["SJQ_SHA_AARCH64_LINUX"],
    "sjq-x86_64-unknown-linux-musl.tar.gz":  os.environ["SJQ_SHA_X86_64_LINUX"],
}

with open(path) as f:
    content = f.read()

# version "x.y.z"  (use \g<N> so a following digit can't merge into the group ref)
content, n = re.subn(r'(?m)^(\s*version ")[^"]+(")', rf'\g<1>{version}\g<2>', content, count=1)
assert n == 1, "version line not found"

for asset, sha in shas.items():
    pat = re.compile(
        r'(url "https://github\.com/vivgrid/sjq/releases/download/)v[^/]+(/'
        + re.escape(asset) + r'")\n(\s*sha256 ")[0-9a-f]{64}(")'
    )
    content, n = pat.subn(rf'\g<1>{tag}\g<2>\n\g<3>{sha}\g<4>', content)
    assert n == 1, f"url/sha block not found for {asset}"

with open(path, "w") as f:
    f.write(content)
print(f"rewrote {path} for {tag}")
EOF

# 3. Commit and push only if something changed.
git add "$FORMULA"
if git diff --cached --quiet; then
  echo "Formula already up to date for $TAG; nothing to do."
  exit 0
fi
git -c user.name="github-actions[bot]" \
    -c user.email="41898282+github-actions[bot]@users.noreply.github.com" \
    commit -m "sjq: bump formula to $TAG" \
           -m "Auto-generated by the vivgrid/sjq release workflow."
git -c "http.https://github.com/.extraHeader=AUTHORIZATION: basic ${auth_header}" \
  push origin HEAD:main
echo "Pushed $TAG to $TAP_REPO."
